/* 📐 👀 Gajjala's Watch — the REAL payload (2026-11-23, vwapzones spec §3.9 [C3]).
 * Ajay 2026-11-23: "can you add vwap and supply demand zone in the daily time frame on the watch list please" · "Add vwap
 * and supply demand too".
 * Reads the JSON the backend writes through the real `payload.build` (backend/scripts/gajjala_watch_fixture_2026_11_23.py
 * → __fixtures__/gajjala_watch_board_2026_11_23.json, regenerated by the main session once both backend packages are in).
 * On EVERY frame with bars, every served `ctx` band that meets the frame's candle range (min low … max high) has a drawn
 * band group — the sub-$1 zero-width (`lo == hi`) band included [C3]; a band the row's text names "inside" is on the
 * chart. NEGATIVES: no served frame is 3-min; an old 1m/3m/5m doc's row serves 1m / 5m / 15m with the 15-min words; the
 * body is NaN-free. Until the JSON exists this file reports itself as waiting (skipped), never green on nothing. */
import { act, cleanup, render } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import GajjalaWatchBoard from './GajjalaWatchBoard';

/* Optional read: null while the backend fixture is not written yet (a missing file never throws — the file reports WAITING). */
const FIXTURE = 'src/components/__fixtures__/gajjala_watch_board_2026_11_23.json';
async function readFixture(): Promise<any> {
  const mod: any = await import(/* @vite-ignore */ ('node:' + 'fs'));
  const fs: any = mod?.default || mod;
  const path = `${(globalThis as any).process?.cwd?.() || '.'}/${FIXTURE}`;
  return fs.existsSync(path) ? JSON.parse(fs.readFileSync(path, 'utf8')) : null;
}
const REAL: any = await readFixture();

const clone = <T,>(x: T): T => JSON.parse(JSON.stringify(x));
type Band = { kind: string; lo: number; hi: number; label?: string; gutter?: string; ctx?: boolean };

async function mount(board: any) {
  vi.stubGlobal('matchMedia', (q: string) => ({ matches: false, media: q, addEventListener: () => {}, removeEventListener: () => {} }));
  vi.stubGlobal('fetch', vi.fn(async () => ({ ok: true, json: async () => clone(board) }) as unknown as Response));
  const r = render(<MemoryRouter initialEntries={['/chart-maps?tab=gajjala_watch&per=9']}><GajjalaWatchBoard /></MemoryRouter>);
  for (let i = 0; i < 3; i += 1) await act(async () => { await vi.advanceTimersByTimeAsync(0); });
  return r;
}
const framesWithBars = (b: any) => (b.rows as any[]).flatMap((r) => (r.frames || [])
  .filter((f: any) => Array.isArray(f?.tile?.bars) && f.tile.bars.length)
  .map((f: any) => ({ sym: r.symbol as string, f, row: r })));
const ctxBands = (f: any): Band[] => (f.tile.bands || []).filter((x: Band) => x && x.ctx === true);
const meets = (z: Band, bars: any[]) => {
  const lo = Math.min(...bars.map((x) => x.l));
  const hi = Math.max(...bars.map((x) => x.h));
  return z.hi >= lo && z.lo <= hi;
};
/** The band's words as the served line names them: its label without the leading "Daily ". */
const words = (z: Band) => (z.label || '').replace(/^Daily\s+/, '');

beforeEach(() => { vi.useFakeTimers(); });
afterEach(() => { cleanup(); vi.useRealTimers(); vi.unstubAllGlobals(); vi.restoreAllMocks(); });

describe.skipIf(!REAL)('📐 the real 2026-11-23 payload (backend payload.build → JSON)', () => {
  it('the fixture carries what the spec asks: zones in range over $1, a sub-$1 zero-width band in range, a retry row, an old-doc row', () => {
    const fw = framesWithBars(REAL);
    expect(fw.some(({ f }) => ctxBands(f).some((z) => meets(z, f.tile.bars) && z.lo > 1))).toBe(true);
    expect(fw.some(({ f }) => ctxBands(f).some((z) => z.lo === z.hi && meets(z, f.tile.bars)))).toBe(true);
    expect((REAL.rows as any[]).some((r) => r.levels?.state === 'retry')).toBe(true);
    expect((REAL.rows as any[]).some((r) => (r.frames || []).some((f: any) => f.tf === '15m' && !f.tile?.bars?.length && f.empty_text))).toBe(true);
  });
  it('NEGATIVE: no served frame is 3-min, every row with frames serves 1m / 5m / 15m in order; NaN-free', () => {
    const body = JSON.stringify(REAL);
    expect(/"3m"|3-min/.test(body), 'a 3-min frame or word in the served body').toBe(false);
    expect(/NaN|Infinity/.test(body), 'NaN / Infinity in the served body').toBe(false);
    for (const r of REAL.rows as any[]) {
      if ((r.frames || []).length) expect((r.frames as any[]).map((f) => f.tf), r.symbol).toEqual(['1m', '5m', '15m']);
    }
  });
  it('[C3] on EVERY frame with bars, every served ctx band meeting the candle range has a drawn band group (zero-width included)', async () => {
    const { container } = await mount(REAL);
    let checked = 0;
    let zeroWidth = 0;
    for (const { sym, f } of framesWithBars(REAL)) {
      const el = container.querySelector(`[data-testid="ggw-frame-${sym}-${f.tf}"]`) as HTMLElement;
      expect(el, `${sym} ${f.tf}`).not.toBeNull();
      const titles = Array.from(el.querySelectorAll('g[data-band-kind] > rect > title')).map((t) => t.textContent);
      for (const z of ctxBands(f)) {
        if (!meets(z, f.tile.bars)) {
          expect(titles, `${sym} ${f.tf} out of range ${z.label}`).not.toContain(z.label);
          continue;
        }
        expect(titles, `${sym} ${f.tf} ${z.label}`).toContain(z.label);
        expect(el.querySelector(`g[data-band-kind="${z.kind}"]`)).not.toBeNull();
        checked += 1;
        if (z.lo === z.hi) zeroWidth += 1;
      }
      // a ctx band never prints an off-chart edge marker
      expect(el.querySelector('g[data-band-kind$="-off"]'), `${sym} ${f.tf}`).toBeNull();
    }
    expect(checked).toBeGreaterThan(0);
    expect(zeroWidth).toBeGreaterThan(0);
  });
  it('a band the row\'s levels text names "inside" is on the chart', async () => {
    const { container } = await mount(REAL);
    let named = 0;
    let rows = 0;
    for (const r of REAL.rows as any[]) {
      const text: string = r.levels?.text || '';
      if (!text.includes('inside ')) continue;
      rows += 1;
      const f1 = (r.frames || []).find((f: any) => f.tf === '1m' && f.tile?.bars?.length);
      if (!f1) continue;
      for (const z of ctxBands(f1)) {
        if (!text.includes(`inside ${words(z)}`)) continue;
        const el = container.querySelector(`[data-testid="ggw-frame-${r.symbol}-1m"]`) as HTMLElement;
        const titles = Array.from(el.querySelectorAll('g[data-band-kind] > rect > title')).map((t) => t.textContent);
        expect(titles, `${r.symbol} ${z.label}`).toContain(z.label);
        named += 1;
      }
    }
    expect(named).toBeGreaterThanOrEqual(rows);   // each "inside" row names a served band, and that band is drawn
  });
  it('every served levels text prints verbatim once in its tile', async () => {
    const { container } = await mount(REAL);
    for (const r of REAL.rows as any[]) {
      if (!r.levels?.text) continue;
      const lines = container.querySelectorAll(`[data-testid="ggw-tile-${r.symbol}"] [data-testid="ggw-levels-${r.symbol}"]`);
      expect(lines, r.symbol).toHaveLength(1);
      expect(lines[0].textContent).toBe(r.levels.text);
    }
  });
});

describe('📐 the real payload — status', () => {
  it(REAL ? 'the backend fixture is present' : 'WAITING: __fixtures__/gajjala_watch_board_2026_11_23.json not written yet (be-watch / main session)', () => {
    expect(REAL === null || typeof REAL === 'object').toBe(true);
  });
});
